tinymce.PluginManager.add('selectcontainer', function (editor) {

    // Balises considérées comme des conteneurs
    var containerTags = editor.getParam('selectcontainer_tags', [
        'P',
        'DIV',
        'FIGURE',
        'SECTION',
        'ARTICLE'
	]);

    function isContainer(node) {
        return node && containerTags.indexOf(node.nodeName) !== -1;
    }

    function getContainer(node) {
        while (node && node !== editor.getBody()) {
            switch (node.nodeName) {
                // Eléments internes d'un média
                case 'SOURCE':
                case 'TRACK':
                    node = node.parentNode;
                    continue;
                // Médias
                case 'IMG':
                case 'VIDEO':
                case 'AUDIO':
                case 'IFRAME':
                case 'OBJECT':
                case 'EMBED':
                    node = node.parentNode;
                    while (node && node !== editor.getBody()) {
                        if (isContainer(node)) {
                            return node;
                        }
                        node = node.parentNode;
                    }
                    return null;
                default:
                    if (isContainer(node)) {
                        return node;
                    }
                    node = node.parentNode;
            }
        }
        return null;
    }

    editor.addCommand('mceSelectContainer', function () {
        var container = getContainer(editor.selection.getNode());
        if (container) {
            editor.focus();
            editor.selection.select(container, true);
            editor.nodeChanged();
        }
    });
	
	editor.ui.registry.addIcon('selectcontainer', `
	<svg width="24" height="24" viewBox="0 0 24 24">
		<rect x="4" y="4" width="16" height="16"
			  fill="none"
			  stroke="currentColor"
			  stroke-width="2"/>
		<rect x="8" y="8" width="8" height="8"
			  fill="currentColor"/>
	</svg>
	`);

    editor.ui.registry.addMenuItem('selectcontainer', {
        text: editor.translate('Select container'),
		icon: 'selectcontainer',
        onAction: function () {
            editor.execCommand('mceSelectContainer');
        }
    });

    return {
        getMetadata: function () {
            return {
                name: 'Select Container',
                url: 'https://deltacms.fr'
            };
        }
    };

});